// Some portions generated by Claude
// Synthetic topology, not a reconstruction of the user's private query results.
// 237 nodes / 326 relations: shared award, people, institutions and RDF details.
export function sharedHubNetwork() {
  const nodes = [];
  const edges = [];
  const addNode = (id, label, kind = 'iri') => {
    const i = nodes.length;
    nodes.push({ id, label, kind, x: 640 + Math.cos(i * 2.399963) * (200 + i * 3), y: 390 + Math.sin(i * 2.399963) * (200 + i * 3) });
  };
  const link = (source, target, label) => edges.push({ id: `e${edges.length}`, source, target, predicate: `urn:${label}`, label });
  addNode('award', 'Shared research award');
  for (let i = 0; i < 72; i++) addNode(`p${i}`, `Researcher ${i} — given and family name`);
  for (let i = 0; i < 64; i++) addNode(`u${i}`, `University ${i} — Institute of natural sciences`);
  for (let i = 0; i < 100; i++) addNode(`d${i}`, `Biographical detail ${i}`, i % 2 ? 'literal' : 'iri');
  for (let i = 0; i < 72; i++) {
    const cluster = Math.floor(i / 9), local = i % 9;
    link(`p${i}`, 'award', 'award');
    link(`p${i}`, `u${cluster * 8 + local % 8}`, 'educated at');
    link(`p${i}`, `u${cluster * 8 + (local + 1) % 8}`, 'employer');
  }
  for (let i = 0; i < 100; i++) link(`p${i % 72}`, `d${i}`, 'detail');
  for (let i = 0; i < 10; i++) link(`p${i * 6}`, `p${i * 6 + 1}`, 'collaborator');
  return { nodes, edges, revision: 1 };
}

export function disconnectedNetwork() {
  const nodes = [], edges = [];
  for (let c = 0; c < 12; c++) {
    for (let i = 0; i < 8; i++) {
      nodes.push({ id: `${c}:${i}`, label: `Component ${c} / node ${i}`, kind: 'iri', x: 0, y: 0 });
      if (i) edges.push({ id: `e${c}:${i}`, source: `${c}:0`, target: `${c}:${i}`, label: 'connected', predicate: 'urn:p' });
    }
  }
  return { nodes, edges, revision: 1 };
}

export function chainNetwork(count = 80) {
  return {
    nodes: Array.from({length: count}, (_, i) => ({id: `${i}`, label: `Step ${i}`, kind: 'iri', x: i * 1000, y: 0})),
    edges: Array.from({length: count - 1}, (_, i) => ({id: `e${i}`, source: `${i}`, target: `${i + 1}`, label: 'next', predicate: 'urn:next'})),
    revision: 1,
  };
}
